#!/usr/bin/env bash
set -Eeuo pipefail

REV="QUANT-NOVA-2.4.22-MORNING-FLOW-SOURCE-RECOVERY-V2"
APP="quant-nova"
BASE="$HOME/quant-nova"
BK="$BASE/morning-flow-recovery-backups"
STAMP="$(date +%Y%m%d%H%M%S)"
WORK="/tmp/nova-morning-recovery-$STAMP"
OLD="$BK/main.py.before-$STAMP"
NEW="$WORK/main.py"
DONOR="$WORK/donor-v2_1.py"
PATCHER="$WORK/patch.py"
SUCCESS=0

mkdir -p "$BK" "$WORK"
chmod 700 "$BK" "$WORK"

rollback() {
  local ec=$?
  [[ $ec -eq 0 || $SUCCESS -eq 1 ]] && return 0
  echo "=== $REV FAILED: ROLLBACK ===" >&2
  if [[ -s "$OLD" ]]; then
    sudo docker cp "$OLD" "$APP:/app/app/main.py" >/dev/null 2>&1 || true
    sudo docker restart "$APP" >/dev/null 2>&1 || true
    sleep 8
  fi
  echo "ROLLBACK=COMPLETE" >&2
}
trap rollback ERR

echo "=== $REV START ==="
echo "DONOR=KNOWN_GOOD_PREMARKET_RERANK_SLOT_STABLE_V2.1"
echo "RECOVERY_SCOPE=OPENING_SHAKEOUT_MORNING_FLOW_ONLY"
echo "SELECTION_LOGIC_CHANGE=NONE"
echo "BUY_THRESHOLDS_CHANGE=NONE"
echo "SCORING_FORMULA_CHANGE=NONE"
echo "PREMARKET_RERANK_LOGIC_CHANGE=NONE"
echo "WS_CONTRACT_CHANGE=NONE"

sudo docker inspect "$APP" >/dev/null
sudo docker cp "$APP:/app/app/main.py" "$OLD"
sudo cp "$OLD" "$NEW"
sudo chown "$(id -u):$(id -g)" "$NEW"
chmod 600 "$NEW"

python3 - "$DONOR" <<'PY'
import base64,gzip,sys
payload = """"""
raw=gzip.decompress(base64.b64decode(payload))
open(sys.argv[1],"wb").write(raw)
print("DONOR_BYTES="+str(len(raw)))
PY

cat > "$PATCHER" <<'PY'
from __future__ import annotations
from pathlib import Path
import ast, hashlib, re, sys

cur_path=Path(sys.argv[1])
donor_path=Path(sys.argv[2])
s=cur_path.read_text(encoding="utf-8")
d=donor_path.read_text(encoding="utf-8")
ct=ast.parse(s)
dt=ast.parse(d)

PROTECTED=[
    "calc","score_codes","ranked","update_sector_context",
    "evaluate_nxt_radar_alerts","build_next_day_close_picks",
    "evaluate_premarket_picks",
]

def fn_node(tree,name):
    for n in ast.walk(tree):
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)) and n.name==name:
            return n
    return None

def fn_text(src,tree,name):
    n=fn_node(tree,name)
    if not n:
        raise SystemExit("FUNCTION_NOT_FOUND:"+name)
    ls=src.splitlines(True)
    return "".join(ls[n.lineno-1:n.end_lineno])

before={}
for name in PROTECTED:
    n=fn_node(ct,name)
    if n:
        before[name]=hashlib.sha256(fn_text(s,ct,name).encode()).hexdigest()

def donor_fn(name):
    return fn_text(d,dt,name).rstrip()+"\n\n"

# ---------- constants / file path ----------
if "OPENING_SHAKEOUT_FILE=" not in s:
    anchor="NXT_NEXT_DAY_PICK_FILE=DATA_DIR/'nxt_next_day_close_picks.json'"
    if anchor not in s:
        raise SystemExit("NXT_NEXT_DAY_PICK_FILE_ANCHOR_NOT_FOUND")
    s=s.replace(anchor,anchor+"\nOPENING_SHAKEOUT_FILE=DATA_DIR/'opening_shakeout_reversal.json'",1)
    print("RECOVER_OPENING_FILE=YES")
else:
    print("RECOVER_OPENING_FILE=ALREADY")

if "OPENING_SHAKEOUT_START_SECONDS=" not in s:
    anchor="NXT_MORNING_PUSH_END_SECONDS=9*3600"
    if anchor not in s:
        raise SystemExit("NXT_MORNING_PUSH_END_ANCHOR_NOT_FOUND")
    consts = """
# OPENING SHAKEOUT -> REVERSAL advisory lane. It never bypasses the existing confirmed BUY engine.
OPENING_SHAKEOUT_START_SECONDS=9*3600
OPENING_SHAKEOUT_END_SECONDS=9*3600+30*60
OPENING_BUY_START_SECONDS=9*3600+10*60
OPENING_BUY_END_SECONDS=10*3600
OPENING_WATCH_LIMIT=max(20,min(40,int(os.getenv('NOVA_OPENING_WATCH_LIMIT','30'))))
OPENING_REVERSAL_LIMIT=max(10,min(20,int(os.getenv('NOVA_OPENING_REVERSAL_LIMIT','15'))))
OPENING_DISPLAY_LIMIT=max(5,min(12,int(os.getenv('NOVA_OPENING_DISPLAY_LIMIT','10'))))
OPENING_READY_LIMIT=max(3,min(5,int(os.getenv('NOVA_OPENING_READY_LIMIT','5'))))
OPENING_FLUSH_MIN_DROP=float(os.getenv('NOVA_OPENING_FLUSH_MIN_DROP','1.8'))
OPENING_FLUSH_MAX_DROP=float(os.getenv('NOVA_OPENING_FLUSH_MAX_DROP','12.0'))
OPENING_MIN_LOW_AGE=max(30,int(os.getenv('NOVA_OPENING_MIN_LOW_AGE','45')))
OPENING_BOARD_MIN_HOLD=max(60,int(os.getenv('NOVA_OPENING_BOARD_MIN_HOLD','150')))
OPENING_REPLACE_MARGIN=max(3.0,float(os.getenv('NOVA_OPENING_REPLACE_MARGIN','7.0')))
"""
    s=s.replace(anchor,anchor+consts,1)
    print("RECOVER_OPENING_CONSTANTS=YES")
else:
    print("RECOVER_OPENING_CONSTANTS=ALREADY")

# ---------- opening engine functions ----------
engine_names=[
    "_load_opening_shakeout",
    "_persist_opening_shakeout",
    "update_opening_shakeout_tick",
    "_opening_shakeout_row",
    "_build_opening_shakeout_payload",
    "opening_shakeout_loop",
]
missing=[n for n in engine_names if not re.search(rf"^(?:async\s+)?def\s+{re.escape(n)}\s*\(",s,re.M)]
if missing:
    anchor="def build_next_day_close_picks("
    pos=s.find(anchor)
    if pos<0:
        raise SystemExit("BUILD_NEXT_DAY_CLOSE_PICKS_ANCHOR_NOT_FOUND")
    block="".join(donor_fn(n) for n in engine_names if n in missing)
    s=s[:pos]+block+s[pos:]
    print("RECOVER_OPENING_FUNCTIONS="+",".join(missing))
else:
    print("RECOVER_OPENING_FUNCTIONS=ALREADY")

# ---------- daily reset ----------
if "STATE.opening_shakeout={'version':'OPENING_SHAKEOUT_REVERSAL_V1'" not in s:
    marker="STATE.morning_push_day=''"
    idx=s.find(marker)
    if idx<0:
        raise SystemExit("MORNING_PUSH_DAY_RESET_ANCHOR_NOT_FOUND")
    end=idx+len(marker)
    s=s[:end]+";STATE.opening_shakeout={'version':'OPENING_SHAKEOUT_REVERSAL_V1','day':day,'rows':{},'board':[],'generated_at':None}"+s[end:]
    print("RECOVER_DAILY_RESET=YES")
else:
    print("RECOVER_DAILY_RESET=ALREADY")

# ---------- realtime KRX tick hook ----------
if "update_opening_shakeout_tick(cand,now,p,venue)" not in s:
    tick_anchor="cand.ticks.append(Tick(now,p,q,rate,venue,cumvol,turnover))"
    if tick_anchor not in s:
        raise SystemExit("TICK_APPEND_ANCHOR_NOT_FOUND")
    s=s.replace(tick_anchor,tick_anchor+"\n                        update_opening_shakeout_tick(cand,now,p,venue)",1)
    print("RECOVER_TICK_HOOK=YES")
else:
    print("RECOVER_TICK_HOOK=ALREADY")

# ---------- runtime factory ----------
if "'nova-opening-shakeout': opening_shakeout_loop" not in s:
    # Add immediately after close-picks runtime slot.
    factory_anchor="'nova-close-picks': close_pick_loop,"
    if factory_anchor not in s:
        raise SystemExit("RUNTIME_CLOSE_PICKS_ANCHOR_NOT_FOUND")
    s=s.replace(factory_anchor,factory_anchor+"\n    'nova-opening-shakeout': opening_shakeout_loop,",1)
    print("RECOVER_RUNTIME_SLOT=YES")
else:
    print("RECOVER_RUNTIME_SLOT=ALREADY")

# ---------- startup load ----------
if "_load_opening_shakeout()" not in s:
    load_anchor="load_next_day_picks();"
    if load_anchor not in s:
        raise SystemExit("LOAD_NEXT_DAY_PICKS_ANCHOR_NOT_FOUND")
    s=s.replace(load_anchor,load_anchor+"_load_opening_shakeout();",1)
    print("RECOVER_STARTUP_LOAD=YES")
else:
    print("RECOVER_STARTUP_LOAD=ALREADY")

# ---------- API route ----------
if "@app.get('/api/opening-shakeout-reversal')" not in s:
    route=donor_fn("opening_shakeout_api")
    # donor_fn excludes decorator, extract decorator+function directly
    dn=fn_node(dt,"opening_shakeout_api")
    dlines=d.splitlines(True)
    start=dn.lineno-1
    while start>0 and dlines[start-1].lstrip().startswith("@"):
        start-=1
    route="".join(dlines[start:dn.end_lineno]).rstrip()+"\n\n"
    route_anchor="@app.get('/api/close-picks')"
    pos=s.find(route_anchor)
    if pos<0:
        raise SystemExit("CLOSE_PICKS_ROUTE_ANCHOR_NOT_FOUND")
    s=s[:pos]+route+s[pos:]
    print("RECOVER_OPENING_ROUTE=YES")
else:
    print("RECOVER_OPENING_ROUTE=ALREADY")

# ---------- EOD screen payload ----------
if "'opening_shakeout':_build_opening_shakeout_payload()" not in s:
    # Insert in the compact payload dict after close_smart_money if available.
    old="'close_smart_money':_build_close_smart_money_payload()"
    if old in s:
        s=s.replace(old,old+",'opening_shakeout':_build_opening_shakeout_payload()",1)
        print("RECOVER_EOD_SNAPSHOT_FIELD=YES")
    else:
        print("RECOVER_EOD_SNAPSHOT_FIELD=SKIP_ANCHOR_NOT_FOUND")
else:
    print("RECOVER_EOD_SNAPSHOT_FIELD=ALREADY")

# ---------- close-picks presentation freshness ----------
# Preserve next_day_picks internally; only stop held EOD snapshot from resurrecting
# previous close picks after 08:50.
m=re.search(
    r"@app\.get\('/api/close-picks'\)\nasync def close_picks_api\(\):\n(?P<body>(?:    .*\n)+?)(?=\n@app\.get\('/api/close-smart-money'\))",
    s
)
if not m:
    raise SystemExit("CLOSE_PICKS_API_BLOCK_NOT_FOUND")
if "held_close_allowed" not in m.group(0):
    replacement="""@app.get('/api/close-picks')
async def close_picks_api():
    sec=kst_seconds()
    d=STATE.next_day_picks or {'rows':[]}
    held_close_allowed=bool(
        str(d.get('effective_day') or '')==today_kst()
        and sec < 8*3600+50*60
    )
    snap=_snapshot_for_display() if held_close_allowed else None
    if snap and isinstance(snap.get('close_picks'),dict):
        out=_held_snapshot_payload_current_version(snap['close_picks'])
        out['screen_hold']=screen_hold_status(snap)
        out['premarket_active']=False
        out['held_until']='08:50'
        return out
    out=_build_close_picks_payload()
    out['screen_hold']=screen_hold_status()
    out['held_until']='08:50'
    if sec >= 8*3600+50*60 and str(d.get('effective_day') or '')==today_kst():
        out['stale_previous_close_hidden']=True
    return out
"""
    s=s[:m.start()]+replacement+s[m.end():]
    print("RECOVER_CLOSE_PICK_DISPLAY_GATE=YES")
else:
    print("RECOVER_CLOSE_PICK_DISPLAY_GATE=ALREADY")

# ---------- syntax + contract ----------
newtree=ast.parse(s)

# Core/trading functions that were present before must remain byte-identical.
for name,h in before.items():
    n=fn_node(newtree,name)
    if not n:
        raise SystemExit("PROTECTED_FUNCTION_DISAPPEARED:"+name)
    h2=hashlib.sha256(fn_text(s,newtree,name).encode()).hexdigest()
    if h2!=h:
        raise SystemExit("PROTECTED_FUNCTION_CHANGED:"+name)

checks={
    "OPENING_START_0900": "OPENING_SHAKEOUT_START_SECONDS=9*3600" in s,
    "OPENING_BUY_END_1000": "OPENING_BUY_END_SECONDS=10*3600" in s,
    "OPENING_PAYLOAD": "def _build_opening_shakeout_payload" in s,
    "OPENING_ROW": "def _opening_shakeout_row" in s,
    "PRIOR_CLOSE": "PRIOR_CLOSE" in s,
    "TODAY_NEW": "TODAY_NEW" in s,
    "TICK_HOOK": "update_opening_shakeout_tick(cand,now,p,venue)" in s,
    "RUNTIME_SLOT": "'nova-opening-shakeout': opening_shakeout_loop" in s,
    "STARTUP_LOAD": "_load_opening_shakeout()" in s,
    "OPENING_ROUTE": "@app.get('/api/opening-shakeout-reversal')" in s,
    "PREMARKET_RERANK": ("premarket_rank" in s or "evaluate_premarket_picks" in s),
    "CLOSE_0850_DISPLAY_GATE": ("held_close_allowed" in s and "stale_previous_close_hidden" in s),
}
for k,v in checks.items():
    print(f"{k}={'PASS' if v else 'FAIL'}")
if not all(checks.values()):
    raise SystemExit("MORNING_FLOW_SOURCE_CONTRACT_FAIL")

cur_path.write_text(s,encoding="utf-8")
compile(s,str(cur_path),"exec")
print("PATCH=PASS")
print("PROTECTED_TRADING_FUNCTION_HASH_GATE=PASS")
print("MORNING_FLOW_SOURCE_CONTRACT=PASS")
PY

echo "=== APPLY RECOVERY PATCH ==="
python3 "$PATCHER" "$NEW" "$DONOR"
python3 -m py_compile "$NEW"
echo "PYTHON_COMPILE=PASS"

echo "=== INSTALL ==="
sudo docker cp "$NEW" "$APP:/app/app/main.py"
sudo docker restart "$APP" >/dev/null

echo "=== READY GATE ==="
READY=0
for i in $(seq 1 25); do
  CODE="$(curl -sS --max-time 2 -o /dev/null -w '%{http_code}' http://127.0.0.1:3200/api/health || true)"
  echo "READY $i code=$CODE"
  if [[ "$CODE" == "200" ]]; then READY=1; break; fi
  sleep 1
done
[[ "$READY" == "1" ]] || { sudo docker logs --tail 120 "$APP" 2>&1 || true; echo "READY_GATE=FAIL" >&2; exit 1; }
echo "READY_GATE=PASS"

echo "=== API CONTRACT ==="
OPEN="$(curl -sS --max-time 3 -o /tmp/opening-v2.json -w '%{http_code}' http://127.0.0.1:3200/api/opening-shakeout-reversal || true)"
CLOSE="$(curl -sS --max-time 3 -o /tmp/close-v2.json -w '%{http_code}' http://127.0.0.1:3200/api/close-picks || true)"
NOVA="$(curl -sS --max-time 3 -o /dev/null -w '%{http_code}' http://127.0.0.1:3200/api/nova || true)"
echo "OPENING_HTTP=$OPEN"
echo "CLOSE_PICKS_HTTP=$CLOSE"
echo "NOVA_HTTP=$NOVA"
[[ "$OPEN" == "200" && "$CLOSE" == "200" && "$NOVA" == "200" ]] || { echo "API_CONTRACT_GATE=FAIL" >&2; exit 1; }
echo "API_CONTRACT_GATE=PASS"

echo "=== PAYLOAD CHECK ==="
python3 - <<'PY'
import json
o=json.load(open('/tmp/opening-v2.json'))
c=json.load(open('/tmp/close-v2.json'))
print("OPENING_SHAKEOUT_WINDOW="+str(o.get('shakeout_window')))
print("OPENING_BUY_WINDOW="+str(o.get('buy_window')))
print("OPENING_WATCH_LIMIT="+str(o.get('watch_limit')))
print("OPENING_REVERSAL_LIMIT="+str(o.get('reversal_limit')))
print("OPENING_DISPLAY_LIMIT="+str(o.get('display_limit')))
print("OPENING_READY_LIMIT="+str(o.get('ready_limit')))
print("CLOSE_VISIBLE="+str(c.get('visible')))
print("CLOSE_COUNT="+str(c.get('count')))
print("CLOSE_HELD_UNTIL="+str(c.get('held_until')))
print("STALE_PREVIOUS_CLOSE_HIDDEN="+str(c.get('stale_previous_close_hidden')))
PY

echo "=== SHORT LIVENESS SOAK ==="
PASS=0
for i in $(seq 1 20); do
  CODE="$(curl -sS --max-time 2 -o /dev/null -w '%{http_code}' http://127.0.0.1:3200/api/health || true)"
  [[ "$CODE" == "200" ]] && PASS=$((PASS+1))
  echo "SOAK $i code=$CODE pass=$PASS"
  sleep 1
done
echo "SOAK_PASS=$PASS/20"
[[ "$PASS" -ge 19 ]] || { echo "SOAK_GATE=FAIL" >&2; exit 1; }
echo "SOAK_GATE=PASS"

echo "=== FINAL SOURCE CONTRACT ==="
sudo docker exec "$APP" python3 - <<'PY'
from pathlib import Path
s=Path('/app/app/main.py').read_text(encoding='utf-8')
checks={
 '09:00_SHAKEOUT':'OPENING_SHAKEOUT_START_SECONDS=9*3600' in s,
 '09:10_BUY_START':'OPENING_BUY_START_SECONDS=9*3600+10*60' in s,
 '10:00_BUY_END':'OPENING_BUY_END_SECONDS=10*3600' in s,
 'PRIOR_CLOSE':'PRIOR_CLOSE' in s,
 'TODAY_NEW':'TODAY_NEW' in s,
 'TOP10':'OPENING_DISPLAY_LIMIT' in s,
 'BUY_READY_MAX5':'OPENING_READY_LIMIT' in s,
 'PREMARKET_RERANK':('premarket_rank' in s or 'evaluate_premarket_picks' in s),
 '08:50_DISPLAY_HIDE':'stale_previous_close_hidden' in s,
}
for k,v in checks.items(): print(f'{k}={"PASS" if v else "FAIL"}')
if not all(checks.values()): raise SystemExit('FINAL_CONTRACT_FAIL')
print('FINAL_MORNING_FLOW_CONTRACT=PASS')
PY

echo "=== SNAPSHOT ==="
IMAGE="quant-nova:2.4.22-morning-flow-source-recovery-v2-${STAMP}"
sudo docker commit "$APP" "$IMAGE" >/dev/null
echo "SNAPSHOT_IMAGE=$IMAGE"

echo "=== FINAL ==="
echo "PRIOR_CLOSE_INTERNAL_STATE=PRESERVED"
echo "09:00_POOL=PRIOR_CLOSE+TODAY_NEW"
echo "09:00-09:30=SHAKEOUT_WATCH_MAX30"
echo "09:10-10:00=REVERSAL_MAX15"
echo "DISPLAY_TOP10=STABLE"
echo "BUY_READY_MAX5=YES"
echo "08:50_AFTER_CLOSE_TABLE=STALE_PREVIOUS_HIDDEN"
echo "SELECTION_LOGIC=UNCHANGED"
echo "BUY_THRESHOLDS=UNCHANGED"
echo "SCORING_FORMULA=UNCHANGED"
echo "PREMARKET_RERANK_LOGIC=UNCHANGED"
echo "WS_CONTRACT=UNCHANGED"
echo "=== $REV PASS ==="
SUCCESS=1
